def plan_file(value):
    import json
    return json.dumps(value, ensure_ascii=False, indent=2) + '\n'


PLAN_NOTE = ' Paketteki {file} örnek plandır; kendi değerlerinizle düzenleyip --plan ile kontrol edin.'
